// BANKFREEZE AI - GET CASE
// DEMO / MOCK DATA ONLY - Case-aware extraction

const input = $input.first().json || {};
const body = input.body || input;
const incomingCase = body.case || {};

const caseId = String(
  incomingCase.case_id ||
  body.case_id ||
  ''
).trim();

const valid = caseId !== '';
const now = new Date().toISOString();

// Case-specific demo registry matching all demo cases
const demoRegistry = {
  'CASE-DEMO-001': {
    bank_name: 'State Bank of India',
    masked_account_number: 'XXXX-XXXX-1001',
    restriction_type: 'DEBIT_FREEZE',
    freeze_reason: 'P2P Disputed Transaction Flagged by Cyber Cell [DEMO DATA]',
    transaction_id: 'TXN-DEMO-001',
    amount: 18500,
    authority: 'Cyber Crime Police Station',
    jurisdiction: 'Cyberabad / Hyderabad, Telangana',
    reference_number: 'LEA-DEMO-001'
  },
  'CASE-DEMO-002': {
    bank_name: 'HDFC Bank',
    masked_account_number: 'XXXX-XXXX-2002',
    restriction_type: 'LIEN_AMOUNT',
    freeze_reason: '1930 National Cyber Crime Reporting Portal Phishing Lien [DEMO DATA]',
    transaction_id: 'TXN-DEMO-002',
    amount: 54200,
    authority: 'National Cyber Crime Reporting Portal (NCRRP)',
    jurisdiction: 'New Delhi / NCR Central',
    reference_number: 'NCRRP-2025-88412'
  },
  'CASE-DEMO-003': {
    bank_name: 'ICICI Bank',
    masked_account_number: 'XXXX-XXXX-3003',
    restriction_type: 'TOTAL_FREEZE',
    freeze_reason: 'Periodic Re-KYC Statutory Non-Compliance Hold [DEMO DATA]',
    transaction_id: 'TXN-DEMO-003',
    amount: 0,
    authority: 'Bank Internal Risk & Compliance',
    jurisdiction: 'Mumbai Central',
    reference_number: 'BNK-KYC-99012'
  },
  'CASE-DEMO-004': {
    bank_name: 'Axis Bank',
    masked_account_number: 'XXXX-XXXX-4004',
    restriction_type: 'TOTAL_FREEZE',
    freeze_reason: 'Magistrate Court Attachment Order under Sec 102 CrPC [DEMO DATA]',
    transaction_id: 'TXN-DEMO-004',
    amount: 250000,
    authority: 'Hon\'ble Chief Metropolitan Magistrate Court',
    jurisdiction: 'Bengaluru Rural District',
    reference_number: 'SEC91-COURT-2025-04'
  },
  'CASE-DEMO-005': {
    bank_name: 'Punjab National Bank',
    masked_account_number: 'XXXX-XXXX-5005',
    restriction_type: 'DEBIT_FREEZE',
    freeze_reason: 'Internal Bank Surveillance Hold - External Reason Unspecified [DEMO DATA]',
    transaction_id: 'TXN-DEMO-005',
    amount: 78000,
    authority: 'AML Suspicious Activity Unit',
    jurisdiction: 'Kolkata Regional Directorate',
    reference_number: 'AML-ALERT-771'
  }
};

const registered = demoRegistry[caseId] || {};

const caseInfo = {
  case_id: caseId || 'CASE-DEMO-UNKNOWN',
  bank_name: incomingCase.bank_name || registered.bank_name || 'NOT PROVIDED',
  masked_account_number: incomingCase.masked_account_number || registered.masked_account_number || 'XXXX-XXXX-XXXX',
  restriction_type: incomingCase.restriction_type || registered.restriction_type || 'NOT PROVIDED',
  freeze_reason: incomingCase.freeze_reason || registered.freeze_reason || 'NOT PROVIDED',
  transaction_id: incomingCase.transaction_id || registered.transaction_id || 'NOT PROVIDED',
  amount: (incomingCase.amount !== undefined && incomingCase.amount !== null) ? incomingCase.amount : (registered.amount !== undefined ? registered.amount : 0),
  authority: incomingCase.authority || registered.authority || 'NOT PROVIDED',
  jurisdiction: incomingCase.jurisdiction || registered.jurisdiction || 'NOT PROVIDED',
  reference_number: incomingCase.reference_number || registered.reference_number || 'NOT PROVIDED',
  status: incomingCase.status || 'NEW'
};

const audit = [
  {
    case_id: caseInfo.case_id,
    timestamp: now,
    workflow_step: 'GET_CASE',
    action: valid ? 'CASE_LOADED' : 'INVALID_CASE_ID',
    result: valid ? 'CASE_LOADED_SUCCESSFULLY' : 'INVALID_CASE_DATA',
    actor: 'system'
  }
];

return [{
  json: {
    valid: valid,
    case_id: caseInfo.case_id,
    case_status: 'NEW',
    source_label: 'DEMO / MOCK DATA',
    case: caseInfo,
    audit_log: audit
  }
}];

// DEMO / MOCK DATA — Case-aware bank verification
const d = $input.first().json;
const c = d.case || {};
const now = new Date().toISOString();

const bank = {
  status: 'RESTRICTED',
  bank_name: c.bank_name || 'NOT PROVIDED',
  restriction_type: c.restriction_type || 'DEBIT_FREEZE',
  reason: c.freeze_reason || 'NOT PROVIDED',
  transaction_id: c.transaction_id || 'NOT PROVIDED',
  amount: c.amount || 0,
  reference_number: c.reference_number || 'NOT PROVIDED',
  requesting_authority: c.authority || 'NOT PROVIDED',
  jurisdiction: c.jurisdiction || 'NOT PROVIDED',
  source_label: 'DEMO / MOCK DATA'
};

const audit = (d.audit_log || []).concat([
  { case_id: d.case_id, timestamp: now, workflow_step: 'BANK_VERIFICATION', action: 'BANK_CHECKED', result: 'RESTRICTED', actor: 'system' }
]);

return [{ json: { ...d, bank, case_status: 'BANK_VERIFICATION', audit_log: audit } }];

const d = $input.first().json;
const now = new Date().toISOString();
const audit = (d.audit_log||[]).concat([
  { case_id:d.case_id, timestamp:now, workflow_step:'ERROR_HANDLING', action:'INVALID_CASE_ID', result:'ROUTED_TO_HUMAN_REVIEW', actor:'system' }
]);
return [{
  json: {
    ...d,
    error: true,
    final_status: 'ERROR',
    user_result: {
      case_information: { case_id: d.case_id || 'UNKNOWN', status: 'INVALID_CASE' },
      investigation_findings: ['Invalid or missing case data in trigger payload.'],
      ai_assessment: { known_information: [], unknown_information: ['Case could not be identified.'], matches: [], conflicts: [], clarification_required: ['Provide a valid case ID.'], next_action: 'RE-VERIFY_CASE_SELECTION' },
      risk_assessment: { risk_level: 'HIGH', reason: 'Invalid or missing case payload.' },
      recommended_action: 'VERIFY_CASE_RECORD',
      human_review: { required: true, decision: 'REJECT', approval_channel: 'system' },
      communication: { status: 'NOT_GENERATED', body: 'No communication generated.' },
      missing_information: ['Valid case identifier'],
      account_action: { action_taken: 'NO AUTOMATIC UNFREEZE', note: 'No account unfreeze performed.' },
      final_status: 'ERROR'
    },
    source_label: 'DEMO / MOCK DATA'
  }
}];

const d = $input.first().json;
const now = new Date().toISOString();
const b = d.bank || {};

const authority = {
  authority_name: b.requesting_authority || 'NOT PROVIDED',
  jurisdiction: b.jurisdiction || 'NOT PROVIDED',
  reference_number: b.reference_number || 'NOT PROVIDED',
  police_officer: 'NOT PROVIDED',
  police_station: 'NOT PROVIDED',
  fir_number: 'NOT PROVIDED',
  complaint_number: 'NOT PROVIDED',
  legal_order: 'NOT PROVIDED',
  contact_details: 'NOT PROVIDED'
};

const audit = (d.audit_log||[]).concat([
  { case_id: d.case_id, timestamp: now, workflow_step: 'AUTHORITY_IDENTIFICATION', action: 'AUTHORITY_IDENTIFIED', result: authority.authority_name, actor: 'system' }
]);

return [{ json: { ...d, authority, case_status: 'AUTHORITY_IDENTIFICATION', audit_log: audit } }];

// DEMO / MOCK DATA — Case-aware mock authority inquiry response
const d = $input.first().json;
const now = new Date().toISOString();
const c = d.case || {};
const b = d.bank || {};

const authority_info = {
  available: c.authority !== 'NOT PROVIDED',
  authority_name: c.authority || b.requesting_authority || 'NOT PROVIDED',
  reference_number: c.reference_number || b.reference_number || 'NOT PROVIDED',
  transaction_id: c.transaction_id || b.transaction_id || 'NOT PROVIDED',
  amount: c.amount || b.amount || 0,
  case_status: 'RECORDED',
  jurisdiction: c.jurisdiction || b.jurisdiction || 'NOT PROVIDED',
  source_label: 'DEMO DATA'
};

const audit = (d.audit_log||[]).concat([
  { case_id: d.case_id, timestamp: now, workflow_step: 'AUTHORITY_INFO', action: 'AUTHORITY_INFO_FETCHED', result: authority_info.available ? 'FETCHED' : 'NOT_PROVIDED', actor: 'system' }
]);

return [{ json: { ...d, authority_info, audit_log: audit } }];

const d = $input.first().json;
const now = new Date().toISOString();
const c = d.case || {};
const b = d.bank || {};
const a = d.authority_info || {};

function norm(v) {
  return (v === undefined || v === null || v === 'NOT PROVIDED' || v === '') ? null : String(v).trim().toLowerCase();
}

function cmp(vals) {
  const raw = vals.map(norm);
  const present = raw.filter(v => v !== null);
  if (present.length < 2) return 'MATCH';
  return present.every(v => v === present[0]) ? 'MATCH' : 'MISMATCH';
}

const comparison = {
  transaction_id: cmp([c.transaction_id, b.transaction_id, a.transaction_id]),
  amount: cmp([c.amount, b.amount, a.amount]),
  freeze_reason: cmp([c.freeze_reason, b.reason]),
  authority: cmp([c.authority, b.requesting_authority, a.authority_name]),
  reference_number: cmp([c.reference_number, b.reference_number, a.reference_number])
};

const isMismatch = d.case_id === 'CASE-DEMO-005' || comparison.transaction_id === 'MISMATCH' || comparison.amount === 'MISMATCH';
const case_risk = isMismatch ? 'INFORMATION_MISMATCH' : (c.case_id === 'CASE-DEMO-004' ? 'HIGH_JUDICIAL_RESTRICTION' : 'NORMAL');

const audit = (d.audit_log||[]).concat([
  { case_id: d.case_id, timestamp: now, workflow_step: 'SOURCE_RECONCILIATION', action: 'SOURCES_COMPARED', result: case_risk, actor: 'system' }
]);

return [{ json: { ...d, comparison, case_risk, case_status: 'CASE_ANALYSIS', audit_log: audit } }];

const d = $input.first().json;
const now = new Date().toISOString();
const audit = (d.audit_log||[]).concat([
  { case_id: d.case_id, timestamp: now, workflow_step: 'SOURCE_RECONCILIATION', action: 'MISMATCH_DETECTED', result: 'AUTOMATIC_COMMUNICATION_STOPPED', actor: 'system' },
  { case_id: d.case_id, timestamp: now, workflow_step: 'UPDATE_STATUS', action: 'STATUS_UPDATED', result: 'USER_REVIEW', actor: 'system' }
]);
return [{ json: { ...d, case_status: 'USER_REVIEW', automatic_processing_stopped: true, audit_log: audit } }];

// Deterministic Case-Aware AI Assessment
const d = $input.first().json;
const now = new Date().toISOString();
const c = d.case || {};
const b = d.bank || {};

const knowns = [
  `Case Identifier: ${c.case_id}`,
  `Restricted Bank: ${c.bank_name} (${c.masked_account_number})`,
  `Nature of Restriction: ${c.restriction_type}`,
  `Recorded Freeze Reason: ${c.freeze_reason}`,
  `Statutory / Notice Ref: ${c.reference_number}`,
  `Identified Authority: ${c.authority} (${c.jurisdiction})`
];

const unknowns = [
  'Investigating Officer direct phone desk number: NOT PROVIDED',
  'Original physical requisition docket: NOT UPLOADED'
];

const matches = [
  `Transaction reference ${c.transaction_id} matches bank record.`,
  `Restriction type ${c.restriction_type} confirmed by ${c.bank_name}.`
];

const conflicts = d.case_risk === 'INFORMATION_MISMATCH' 
  ? ['Internal bank surveillance alert conflicts with external police report.'] 
  : ['No conflicting values detected across submitted sources.'];

const clarification_required = [
  'Confirm whether lien can be isolated to disputed amount.',
  'Request certified copy of requisition from bank nodal desk.'
];

let next_action = 'DISPATCH_FACTUAL_REPRESENTATION';
if (c.case_id === 'CASE-DEMO-004') {
  next_action = 'SUBMIT_LEGAL_REPRESENTATION_AND_APPEARANCE';
} else if (c.case_id === 'CASE-DEMO-003') {
  next_action = 'SUBMIT_RE_KYC_DOCUMENTS_TO_BRANCH';
} else if (c.case_id === 'CASE-DEMO-005') {
  next_action = 'REQUEST_INTERNAL_AML_CLARIFICATION';
}

const ai_assessment = {
  known_information: knowns,
  unknown_information: unknowns,
  matches: matches,
  conflicts: conflicts,
  clarification_required: clarification_required,
  next_action: next_action
};

const audit = (d.audit_log||[]).concat([
  { case_id: d.case_id, timestamp: now, workflow_step: 'CASE_ANALYSIS', action: 'AI_ANALYSIS_COMPLETED', result: 'ANALYSIS_GENERATED', actor: 'ai_agent' }
]);

return [{ json: { ...d, ai_assessment, case_status: 'CASE_ANALYSIS', audit_log: audit } }];

const d = $input.first().json;
const now = new Date().toISOString();
const c = d.case || {};
const next_action = (d.ai_assessment && d.ai_assessment.next_action) || 'REQUEST_CLARIFICATION';

const action_plan = {
  next_action: next_action,
  reason: `Procedural resolution recommendation for case ${c.case_id} (${c.bank_name})`,
  required_information: ['Case reference verification', 'Applicable review procedure'],
  human_review_required: true
};

const audit = (d.audit_log||[]).concat([
  { case_id: d.case_id, timestamp: now, workflow_step: 'ACTION_PLAN', action: 'ACTION_PLAN_GENERATED', result: action_plan.next_action, actor: 'system' }
]);

return [{ json: { ...d, action_plan, case_status: 'ACTION_REQUIRED', audit_log: audit } }];

const d = $input.first().json;
const now = new Date().toISOString();
const c = d.case || {};
const comm_type = d.authority_info && d.authority_info.available ? 'AUTHORITY_CLARIFICATION' : 'BANK_CLARIFICATION';
const subject = `Clarification request regarding case ${c.case_id} / Ref: ${c.reference_number} (DEMO)`;

const bodyLines = [
  'This is a DEMO communication draft generated by BankFreeze AI. It has NOT been sent to any real party.',
  '',
  `Case reference: ${c.case_id}`,
  `Bank: ${c.bank_name || 'NOT PROVIDED'}`,
  `Masked account: ${c.masked_account_number || 'NOT PROVIDED'}`,
  `Restriction type: ${c.restriction_type || 'NOT PROVIDED'}`,
  `Reference number: ${c.reference_number || 'NOT PROVIDED'}`,
  `Target Authority: ${(d.authority && d.authority.authority_name) || 'NOT PROVIDED'}`,
  '',
  'Request: We respectfully request clarification on the applicable review procedure and confirmation of the reference details associated with this restriction. No sensitive credentials (PIN/OTP/password) are transmitted or requested.'
];

const communication_draft = {
  type: comm_type,
  subject: subject,
  body: bodyLines.join('\n'),
  based_on: 'verified mock data only'
};

const audit = (d.audit_log||[]).concat([
  { case_id: d.case_id, timestamp: now, workflow_step: 'COMMUNICATION_DRAFT', action: 'COMMUNICATION_GENERATED', result: comm_type, actor: 'system' }
]);

return [{ json: { ...d, communication_draft, case_status: 'ACTION_REQUIRED', audit_log: audit } }];

const c = $input.first().json;
const decision = 'APPROVE';
const body = c.communication_draft.body;
return [{ json: { ...c, approval_decision: decision, approval_channel: 'demo_input', communication_body: body, approved_at: new Date().toISOString() } }];

const d = $input.first().json;
const now = new Date().toISOString();
const audit = (d.audit_log||[]).concat([
  { case_id: d.case_id, timestamp: now, workflow_step: 'HUMAN_APPROVAL', action: 'HUMAN_APPROVAL_RECEIVED', result: d.approval_decision, actor: 'human' },
  { case_id: d.case_id, timestamp: now, workflow_step: 'UPDATE_STATUS', action: 'STATUS_UPDATED', result: 'COMPLETED', actor: 'system' }
]);
return [{ json: { ...d, case_status: 'APPROVED', audit_log: audit } }];

// BANKFREEZE AI - WORKFLOW COMPLETE
// Compiles the exact structured JSON response for Streamlit dashboard
const d = $input.first().json;
const c = d.case || {};
const b = d.bank || {};
const a = d.authority_info || {};
const ai = d.ai_assessment || {};
const ap = d.action_plan || {};
const cd = d.communication_draft || {};

const findings = [
  `Bank Verification (${c.bank_name}): Status confirmed as ${b.status || 'RESTRICTED'} (${c.restriction_type}).`,
  `Freeze Basis: ${c.freeze_reason}.`,
  `Disputed Transaction ID: ${c.transaction_id || 'NOT PROVIDED'} (Amount: ₹${c.amount || 0}).`,
  `Requisitioning Body: ${c.authority || 'NOT PROVIDED'} (${c.jurisdiction || 'NOT PROVIDED'}).`
];

const missing = (c.case_id === 'CASE-DEMO-005') 
  ? ['Documentary grounds for internal AML hold'] 
  : ((c.case_id === 'CASE-DEMO-004') ? ['Certified copy of Magistrate order schedule'] : ['Physical requisition copy from IO']);

const structuredResult = {
  case_id: d.case_id,
  final_status: 'COMPLETED',
  user_result: {
    case_information: {
      case_id: d.case_id,
      bank_name: c.bank_name || 'NOT PROVIDED',
      masked_account_number: c.masked_account_number || 'NOT PROVIDED',
      restriction_type: c.restriction_type || 'NOT PROVIDED',
      freeze_reason: c.freeze_reason || 'NOT PROVIDED',
      status: 'COMPLETED'
    },
    investigation_findings: findings,
    ai_assessment: {
      known_information: ai.known_information || [],
      unknown_information: ai.unknown_information || [],
      matches: ai.matches || [],
      conflicts: ai.conflicts || [],
      clarification_required: ai.clarification_required || [],
      next_action: ai.next_action || 'REQUEST_CLARIFICATION'
    },
    risk_assessment: {
      risk_level: d.case_risk || 'NORMAL',
      reason: `Investigation assessment completed for case ${d.case_id}.`
    },
    recommended_action: ap.next_action || 'REQUEST_CLARIFICATION',
    human_review: {
      required: true,
      decision: d.approval_decision || 'APPROVED',
      approval_channel: d.approval_channel || 'demo_input'
    },
    communication: {
      status: 'DEMO_RECORDED',
      subject: cd.subject || '',
      body: d.communication_body || cd.body || ''
    },
    missing_information: missing,
    account_action: {
      action_taken: 'NO AUTOMATIC UNFREEZE',
      note: 'No automatic account unfreeze is performed by this prototype.'
    },
    final_status: 'COMPLETED'
  },
  source_label: 'DEMO / MOCK DATA'
};

return [{ json: structuredResult }];
